-- PT107-S4-Q12. Batch 07.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch07$PT107-S4-Q12$batch07$ AND q.stimulus=$batch07$Editorialist: Drivers with a large number of demerit points who additionally have been convicted of a serious driving-related offense should either be sentenced to jail or be forced to receive driver re-education, since to do otherwise would be to allow a crime to go unpunished. Only if such drivers are likely to be made more responsible drivers should driver re-education be recommended for them. Unfortunately, it is always almost impossible to make drivers with a large number of demerit points more responsible drivers.$batch07$ AND q.prompt=$batch07$If the editorialist's statements are true, they provide the most support for which one of the following?$batch07$ AND q.correct_choice=$batch07$A$batch07$) THEN RAISE EXCEPTION 'Question changed: PT107-S4-Q12'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch07$PT107-S4-Q12$batch07$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT107-S4-Q12'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch07$PT107-S4-Q12$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch07$Statements$batch07$, $batch07$Drivers with many demerit points and a serious driving conviction should get jail or driver re-education. Re-education should be recommended only if it is likely to make them more responsible. But it is almost always impossible to make such drivers more responsible.$batch07$), (1, $batch07$Evaluate$batch07$, $batch07$Diagram the middle rule: re-education recommended → likely to become more responsible. The last sentence denies the right side: these drivers are almost never going to become more responsible. Contrapositive: so re-education shouldn't be recommended. The first sentence gives only two options, jail or re-education. Knock one out and the other is left.$batch07$), (2, $batch07$Goal$batch07$, $batch07$These drivers should go to jail.$batch07$)) v(position,label,body) WHERE q.qid=$batch07$PT107-S4-Q12$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch07$A$batch07$, $batch07$Two options, and the rules eliminate re-education. Jail is what remains.$batch07$), ($batch07$B$batch07$, $batch07$The editorialist says it's almost impossible to make these drivers more responsible, re-education included.$batch07$), ($batch07$C$batch07$, $batch07$This is the most popular wrong answer. It reaches the right result for the wrong reason. Re-education is ruled out because it won't *work*, not because it isn't *harsh enough*. Harshness never comes up.$batch07$), ($batch07$D$batch07$, $batch07$The rules are about drivers *with* a serious conviction. We can't say anything about drivers without one.$batch07$), ($batch07$E$batch07$, $batch07$Same problem. Drivers with no serious conviction are outside every rule in the passage.$batch07$)) v(letter,body) WHERE q.qid=$batch07$PT107-S4-Q12$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
